		public global::Dpr.Contest.AContestPlayerData[] CreateContestEntryPlayerDataArray() {
			if (!ContestWork.IsMultiMode)
				CreateSingleModeNPCDatas();
			var playerDataArray = new AContestPlayerData[ContestDataConstants.MAX_PARTICIPANT_NUM];
			for (int i = 0; i < ContestWork.entryPlayerDatas.Length; i++)
			{
				// the User case passes the element loaded for the switch (no second static read, 01c662e0)
				EntryPlayerData entryPlayerData = ContestWork.entryPlayerDatas[i];
				switch (entryPlayerData.playerType)
				{
					case PlayerType.User:
						playerDataArray[i] = CreateUserPlayerData(i, entryPlayerData);
						break;
					case PlayerType.NPC:
						// ONE static read feeds both the null test and the index test (01c66338)
						if (ContestWork.entryPlayerDatas[i]?.npcDataIndex >= 0)
							playerDataArray[i] = CreateNPCPlayerData(i, ContestWork.entryPlayerDatas[i]);
						else
							ContestUtils.EmitLog(string.Format("Entry {0} : NPC Data Not Found", i), LogType.Error);
						break;
					default:
						// shipped: an inactive gamer's slot is filled with NPC data from the same entry (01c663f0)
						if (Dpr.NetworkUtils.NetworkManager.Instance.IsGamerActive(i))
							playerDataArray[i] = CreateOtherPlayerData(i, ContestWork.entryPlayerDatas[i]);
						else
							playerDataArray[i] = CreateNPCPlayerData(i, ContestWork.entryPlayerDatas[i]);
						break;
				}
			}
			return playerDataArray;
		}
		private void CreateSingleModeNPCDatas() {
			LotteryNPCData[] lotteryNPCDatas = ContestUtils.CreateLoatteryNPCDataByCategoryAndRank(contestMasterDatas.NPCData, ContestWork.categoryID, ContestWork.rankID, 3);
			if (lotteryNPCDatas.Length < 3)
			{
				ContestUtils.EmitLog(string.Format("Failed Create NPC Data : Create Num {0}", lotteryNPCDatas.Length), LogType.Error);
				return;
			}
			for (int i = 0; i < lotteryNPCDatas.Length; i++)
			{
				// bounds-check order entryPlayerDatas[i + 1] -> lotteryNPCDatas[i] -> NPCData[index] before any store (01c6d438)
				EntryPlayerData entryPlayerData = ContestWork.entryPlayerDatas[i + 1];
				LotteryNPCData lotteryNPCData = lotteryNPCDatas[i];
				ContestMasterDatas.SheetNPCData npcData = contestMasterDatas.NPCData[lotteryNPCData.npcDataIndex];
				entryPlayerData.npcDataIndex = lotteryNPCData.npcDataIndex;
				entryPlayerData.npcWazaNo = lotteryNPCData.useWazaNo;
				entryPlayerData.colorID = GameData.DataManager.TrainerTable.TrainerData[npcData.trainerType].ColorID;
			}
		}
		private void SetPlayerCommonParam(global::Dpr.Contest.AContestPlayerData playerData, global::Dpr.Contest.EntryPlayerData entryPlayerData) {
			playerData.playerType = entryPlayerData.playerType;
			playerData.playerInfo.nickname = entryPlayerData.playerName;
			playerData.playerInfo.langID = entryPlayerData.userLangID;
			if (playerData.playerInfo.langID == 0)
			{
				ContestUtils.EmitLog(string.Format("Player[{0}] : Lang ID is 0!!", playerData.index));
				playerData.playerInfo.langID = MessageManager.Instance.UserLanguageID;
			}
			playerData.playerInfo.sex = entryPlayerData.playerSex;
			playerData.modelColorID = entryPlayerData.colorID;
			playerData.pokemonInfo = CreatePokemonInfo(entryPlayerData);
			playerData.danceDataModel.contestSkill = CreateContestSkill(Pml.WazaData.WazaDataSystem.GetContestWazaNo(playerData.pokemonInfo.wazaNo), playerData.pokemonInfo.wazaType, playerData);
			PokemonParam pokeParam = playerData.pokemonInfo.pokeParam;
			bool validFlag = pokeParam.StartFastMode();
			var catalog = GameData.DataManager.GetPokemonCatalog(pokeParam.GetMonsNo(), pokeParam.GetFormNo(), pokeParam.GetSex(), pokeParam.IsRare(), false);
			playerData.pokemonInfo.size = catalog.ContestSize;
			playerData.pokemonModelPath = CreatePokeModelPath(catalog.AssetBundleName);
			playerData.ballInfo = entryPlayerData.ballInfo;
			playerData.ballModelPath = Dpr.SubContents.Utils.GetBallModelPath(playerData.ballInfo.ballId);
			var btlPokeParam = new Dpr.Battle.Logic.BTL_POKEPARAM();
			var setupParam = new Dpr.Battle.Logic.BTL_POKEPARAM.SetupParam();
			setupParam.srcParam = pokeParam;
			btlPokeParam.Setup(setupParam);
			playerData.pokemonInfo.btlPokeParam = btlPokeParam;
			pokeParam.EndFastMode(validFlag);
		}
		private global::Dpr.Contest.ContestUserData CreateUserPlayerData(int entryNumber, global::Dpr.Contest.EntryPlayerData entryPlayerData) {
			var userData = new ContestUserData();
			userData.index = entryNumber;
			userIndex = entryNumber;
			userData.playerInfo.trainerType = GameData.DataManager.TrainerTable.TrainerType[(int)entryPlayerData.playerSex];
			SetPlayerCommonParam(userData, entryPlayerData);
			userData.visualDataModel.SetScore(CalcVisualScoreByCapsuleData(userData.ballInfo.affixSealDatas), CalcItemScore(userData.pokemonInfo.haveItemNo), CalcVisualScore(userData.pokemonInfo.pokeParam, true), GetValueData(7));
			userData.trainerModelPath = ContestUtils.CreateTrainerModelPath(entryPlayerData.fashion);
			userData.trainerType = ContestUtils.CreateTrainerType(true, entryPlayerData.playerSex);
			// chained stores: wazaCaptureData first, then mainCaptureData (01c6d6d0 / 01c6d6d8)
			mainCaptureData.monsNickName = wazaCaptureData.monsNickName = userData.pokemonInfo.nickname;
			mainCaptureData.languageId = wazaCaptureData.languageId = (byte)userData.pokemonInfo.langID;
			mainCaptureData.userRank = wazaCaptureData.userRank = userContestRank;
			// pokemonInfo held in x21 across the CoreParam calls (01c6d710) = a local
			PokemonInfo pokemonInfo = userData.pokemonInfo;
			mainCaptureData.monsNo = wazaCaptureData.monsNo = (int)pokemonInfo.pokeParam.GetMonsNo();
			wazaCaptureData.wazaNo = (int)pokemonInfo.wazaNo;
			mainCaptureData.formNo = wazaCaptureData.formNo = pokemonInfo.pokeParam.GetFormNo();
			mainCaptureData.sex = wazaCaptureData.sex = (int)pokemonInfo.pokeParam.GetSex();
			mainCaptureData.rare = wazaCaptureData.rare = pokemonInfo.pokeParam.IsRare();
			return userData;
		}
		private global::Dpr.Contest.ContestNPCData CreateNPCPlayerData(int entryNumber, global::Dpr.Contest.EntryPlayerData entryPlayerData) {
			var npcPlayerData = new ContestNPCData();
			npcPlayerData.playerType = PlayerType.NPC;
			npcPlayerData.index = entryNumber;
			ContestMasterDatas.SheetNPCData npcData = contestMasterDatas.NPCData[entryPlayerData.npcDataIndex];
			ContestUtils.EmitLog(string.Format("Lot NPC Data ID : {0} - Trainer ID : {1}", npcData.id, npcData.trainerType));
			entryPlayerData.userLangID = entryPlayerData.monsLangID = MessageManager.Instance.UserLanguageID;
			entryPlayerData.playerName = nameMsgFile.GetNameStr(npcData.trainerLabelName);
			entryPlayerData.monsNo = (MonsNo)npcData.monsNo;
			entryPlayerData.pokemonNickName = nameMsgFile.GetNameStr(npcData.monsLabelName);
			entryPlayerData.formNo = 0;
			entryPlayerData.isRare = false;
			// read once (w25) and reused after every call = a local
			int trainerType = npcData.trainerType;
			npcPlayerData.playerInfo.trainerType = GameData.DataManager.TrainerTable.TrainerType[trainerType];
			if (npcPlayerData.playerInfo.trainerType.TrainerID == Dpr.Trainer.TrainerType.MOTHER)
				entryPlayerData.colorID = PlayerWork.colorID;
			else
				entryPlayerData.colorID = GameData.DataManager.TrainerTable.TrainerData[trainerType].ColorID;
			entryPlayerData.playerSex = (Sex)npcPlayerData.playerInfo.trainerType.Sex;
			entryPlayerData.style = (byte)(npcData.styleValue / 100f);
			entryPlayerData.beautiful = (byte)(npcData.beautifulValue / 100f);
			entryPlayerData.cute = (byte)(npcData.cuteValue / 100f);
			entryPlayerData.clever = (byte)(npcData.cleverValue / 100f);
			entryPlayerData.strong = (byte)(npcData.strongValue / 100f);
			entryPlayerData.fur = (byte)(npcData.furValue / 100f);
			entryPlayerData.ballInfo = CreateNPCBallInfo(npcCapsuleTable[npcData.useCapsuleNo]);
			entryPlayerData.wazaNo = entryPlayerData.npcWazaNo;
			SetPlayerCommonParam(npcPlayerData, entryPlayerData);
			// GetNPCVisualScore inlined (same case map as its own byte table @03d5b76b)
			npcPlayerData.visualDataModel.SetScore(GetNPCVisualScore(npcData), 0, 0, GetValueData(7));
			npcPlayerData.trainerModelPath = string.Format("persons/battle/{0}", npcPlayerData.playerInfo.trainerType.ModelID);
			npcPlayerData.trainerType = (Dpr.Trainer.TrainerType)trainerType;
			npcPlayerData.npcLevel = npcData.npcLevel;
			npcPlayerData.levelData = System.Array.Find(contestMasterDatas.NPCLevelData, x => x.npcLevel == npcData.npcLevel);
			return npcPlayerData;
		}
		private int GetNPCVisualScore(global::XLSXContent.ContestMasterDatas.SheetNPCData data) {
			switch ((CategoryID)useContestData.category)
			{
				case CategoryID.Style:
					return data.styleVisualScore;
				case CategoryID.Beautiful:
					return data.beautifulVisualScore;
				case CategoryID.Cute:
					return data.cuteVisualScore;
				case CategoryID.Clever:
					return data.cleverVisualScore;
				case CategoryID.Tutorial:
					return data.tutorialVisualScore;
				case CategoryID.Fur:
					return data.furVisualScore;
				default:
					return data.strongVisualScore;
			}
		}
		private global::Dpr.Battle.View.BtlvBallInfo CreateNPCBallInfo(global::XLSXContent.ContestMasterDatas.SheetNPCCapsuleData npcCapsuleData) {
			var ballInfo = new BtlvBallInfo();
			ballInfo.ballId = (BallId)npcCapsuleData.ballId;
			AffixSealData[] affixSealDatas = ContestUtils.CreateNPCAffixSealDataArray(npcCapsuleData);
			for (int i = 0; i < affixSealDatas.Length; i++)
			{
				if (affixSealDatas[i].SealId != 0)
					ballInfo.sealCnt++;
			}
			if (ballInfo.sealCnt != 0)
				ballInfo.affixSealDatas = affixSealDatas;
			else
				ballInfo.affixSealDatas = null;
			return ballInfo;
		}
