			SetPlayerCommonParam(otherUserData, entryPlayerData);
			otherUserData.visualDataModel.SetScore(CalcVisualScoreByCapsuleData(otherUserData.ballInfo.affixSealDatas), CalcItemScore(otherUserData.pokemonInfo.haveItemNo), CalcVisualScore(otherUserData.pokemonInfo.pokeParam, true), GetValueData(7));
			otherUserData.trainerModelPath = ContestUtils.CreateTrainerModelPath(entryPlayerData.fashion);
			otherUserData.trainerType = ContestUtils.CreateTrainerType(false, entryPlayerData.playerSex);
			ContestMasterDatas.SheetNPCData npcData = contestMasterDatas.NPCData[entryPlayerData.npcDataIndex];
			otherUserData.npcLevel = npcData.npcLevel;
			otherUserData.levelData = System.Array.Find(contestMasterDatas.NPCLevelData, x => x.npcLevel == npcData.npcLevel);
			return otherUserData;
		}
		private global::Dpr.Contest.PokemonInfo CreatePokemonInfo(global::Dpr.Contest.EntryPlayerData entryPlayerData) {
			var pokemonInfo = new PokemonInfo();
			PokemonParam pokeParam;
			if (entryPlayerData.monsNo == MonsNo.NULL)
			{
				ContestUtils.EmitLog("Player Party Count is 0!!!!!", LogType.Warning);
				pokeParam = new PokemonParam((MonsNo)1, 1, 0);
				pokeParam.SetLangId((uint)MessageManager.Instance.UserLanguageID);
			}
			else
			{
				pokeParam = new PokemonParam(entryPlayerData.monsNo, 1, 0);
				pokemonInfo.isZIBAKOIRU = entryPlayerData.monsNo == MonsNo.ZIBAKOIRU;
				ContestUtils.EmitLog(string.Format("Mons No : {0} - Flag [{1}]", entryPlayerData.monsNo, pokemonInfo.isZIBAKOIRU));
			}
			if (entryPlayerData.monsSex != Sex.NUM)
				pokeParam.ChangeSex(entryPlayerData.monsSex);
			pokeParam.ChangeFormNo((ushort)entryPlayerData.formNo);
			pokeParam.SetItem(entryPlayerData.itemNo);
			if (entryPlayerData.isRare)
			{
				pokeParam.SetRare();
				pokeParam.SetRareType(entryPlayerData.rareType);
			}
			else
			{
				pokeParam.SetNotRare();
			}
			pokeParam.SetCondition(Condition.STYLE, entryPlayerData.style);
			pokeParam.SetCondition(Condition.BEAUTIFUL, entryPlayerData.beautiful);
			pokeParam.SetCondition(Condition.CUTE, entryPlayerData.cute);
			pokeParam.SetCondition(Condition.CLEVER, entryPlayerData.clever);
			pokeParam.SetCondition(Condition.STRONG, entryPlayerData.strong);
			pokeParam.SetCondition(Condition.FUR, entryPlayerData.fur);
			pokemonInfo.pokeParam = pokeParam;
			if (entryPlayerData.wazaNo != WazaNo.NULL)
			{
				pokemonInfo.wazaNo = entryPlayerData.wazaNo;
			}
			else
			{
				pokemonInfo.wazaNo = (WazaNo)1;
				ContestUtils.EmitLog("[" + entryPlayerData.playerName + "] : WazaNo is NULL!!", LogType.Error);
			}
			pokemonInfo.wazaName = wazaNameMsgFile.GetNameStr((int)pokemonInfo.wazaNo);
			pokemonInfo.wazaType = (PokeType)Pml.WazaData.WazaDataSystem.GetType(pokemonInfo.wazaNo);
			pokemonInfo.wazaSeqTime = entryPlayerData.wazaSeqTime;
			pokemonInfo.haveItemNo = entryPlayerData.itemNo;
			pokemonInfo.nickname = entryPlayerData.pokemonNickName;
			pokemonInfo.langID = entryPlayerData.monsLangID;
			pokemonInfo.pokeParam.SetLangId((uint)entryPlayerData.monsLangID);
			return pokemonInfo;
		}
