		private int CalcVisualScore(global::Pml.PokePara.CoreParam pokeParam, bool isPlayer) {
			if (useContestData == null)
				return 0;
			float score = 0f;
			score += CalcConditionScore(pokeParam.GetCondition(Condition.STYLE), useContestData.styleCompatibility);
			score += CalcConditionScore(pokeParam.GetCondition(Condition.BEAUTIFUL), useContestData.beautifulCompatibility);
			score += CalcConditionScore(pokeParam.GetCondition(Condition.CUTE), useContestData.cuteCompatibility);
			score += CalcConditionScore(pokeParam.GetCondition(Condition.CLEVER), useContestData.cleverCompatibility);
			score += CalcConditionScore(pokeParam.GetCondition(Condition.STRONG), useContestData.strongCompatibility);
			score += CalcConditionScore(pokeParam.GetCondition(Condition.FUR), useContestData.furCompatibility);
			return (int)(isPlayer ? score * 100f : score);
		}
		private float CalcConditionScore(byte conditionValue, int compatibility) {
			if (compatibility == (int)Compatibility.None)
				return 0f;
			// FindConditionDataByParameter inlined (01c6ef2c)
			ContestMasterDatas.SheetConditionScoreData conditionData = FindConditionDataByParameter(conditionValue);
			int compatibilityValue;
			switch ((Compatibility)compatibility)
			{
				case Compatibility.Best:
					compatibilityValue = conditionData.bestCompatibility;
					break;
				case Compatibility.Okay:
					compatibilityValue = conditionData.okayCompatibility;
					break;
				default:
					ContestUtils.EmitLog(string.Format("InValid Compatibility ID : {0}", (Compatibility)compatibility), LogType.Error);
					return 0f;
			}
			return conditionData.visualScoreFactor * compatibilityValue;
		}
		private global::XLSXContent.ContestMasterDatas.SheetConditionScoreData FindConditionDataByParameter(int parameter) {
			ContestMasterDatas.SheetConditionScoreData[] conditionScoreDatas = contestMasterDatas.ConditionScoreData;
			for (int i = 0; i < conditionScoreDatas.Length; i++)
			{
				if (conditionScoreDatas[i].conditionValue <= parameter)
					return conditionScoreDatas[i];
			}
			return conditionScoreDatas[conditionScoreDatas.Length - 1];
		}
		private int CalcVisualScoreByCapsuleData(global::Dpr.BallDeco.AffixSealData[] affixSealData) {
			if (affixSealData == null || affixSealData.Length <= 0)
				return 0;
			// the category is read once before the loop (01c6e8bc) and the loop is unswitched on it = a local
			var category = (CategoryID)useContestData.category;
			int score = 0;
			for (int i = 0; i < affixSealData.Length; i++)
			{
				if (affixSealData[i].SealId == 0)
					continue;
				ContestMasterDatas.SheetSealData sealData = sealDataTable[affixSealData[i].SealId];
				switch (category)
				{
					case CategoryID.Style:
						score += sealData.stylePoint;
						break;
					case CategoryID.Beautiful:
						score += sealData.beautifulPoint;
						break;
					case CategoryID.Cute:
						score += sealData.cutePoint;
						break;
					case CategoryID.Clever:
						score += sealData.cleverPoint;
						break;
					case CategoryID.Strong:
						score += sealData.strongPoint;
						break;
					case CategoryID.Tutorial:
						score += sealData.tutorialPoint;
						break;
					case CategoryID.Fur:
						score += sealData.furPoint;
						break;
				}
			}
			return score;
		}
		private int CalcItemScore(int itemNo) {
			ContestUtils.EmitLog(string.Format("Check Item No : [{0}]", itemNo));
			if (itemDataTable.ContainsKey(itemNo))
			{
				ContestMasterDatas.SheetItemData itemData = itemDataTable[itemNo];
				switch ((CategoryID)useContestData.category)
				{
					case CategoryID.Style:
						return itemData.stylePoint;
					case CategoryID.Beautiful:
						return itemData.beautifulPoint;
					case CategoryID.Cute:
						return itemData.cutePoint;
					case CategoryID.Clever:
						return itemData.cleverPoint;
					case CategoryID.Strong:
						return itemData.strongPoint;
					case CategoryID.Tutorial:
						return itemData.tutorialPoint;
					case CategoryID.Fur:
						return itemData.furPoint;
				}
			}
			return 0;
		}
