		public void OnFindCaptureCommand(global::Dpr.Contest.ContestViewSystem targetViewSystem) {
			// IsCaptureContest inlined (its prologue flag 0x4cbdb45 is the only flag here)
			if (IsCaptureContest() && targetViewSystem.SystemType != ContestViewSystem.ViewSystemType.Waza)
			{
				captureCommandNum++;
				maxCaptureCommandNum++;
			}
		}
		public void OnPerformCaptureCommand(global::Dpr.Contest.ContestViewSystem targetViewSystem, global::Dpr.SequenceEditor.Macro macro) {
			// IsCaptureContest inlined (flag 0x4cbdb45 after the method's own 0x4cbdb44)
			if (!IsCaptureContest())
				return;
			ContestPlayerEntity userEntity = SceneObjectManager.Instance.GetUserEntity();
			if (targetViewSystem.SystemType == ContestViewSystem.ViewSystemType.Waza)
			{
				if (wazaCaptureData.bAlreadyCapture)
					return;
				if (!userEntity.IsActiveWazaPokemon && wazaCaptureData.wazaNo != (int)WazaNo.MIGAWARI)
				{
					ContestUtils.EmitLog("Can not Waza Capture : Waza Pokemon InActive!!", LogType.Error);
					return;
				}
				wazaCaptureData.viewSystemPtr = targetViewSystem;
				SetCaptureData(wazaCaptureData);
			}
			else
			{
				if (SceneObjectManager.Instance.IsPlayingUserWaza)
				{
					captureCommandNum--;
					return;
				}
				if (mainCaptureData.bAlreadyCapture)
					return;
				if (!userEntity.IsActiveBOPokemon)
				{
					ContestUtils.EmitLog("Can not Waza Capture : Main Pokemon InActive!!", LogType.Error);
					return;
				}
				if (macro is ContestCaptureScene captureScene)
				{
					// CheckCaptureProbability inlined (capturePersent read before the decrement, 01c690f4)
					if (!CheckCaptureProbability(captureScene.capturePersent))
						return;
					mainCaptureData.viewSystemPtr = targetViewSystem;
					SetCaptureData(mainCaptureData);
				}
			}
		}
		private void SetWazaEffectData(global::Dpr.Contest.CaptureData targetData) {
			Dpr.Battle.View.Systems.BattleSequenceSystem sequenceSystem = targetData.viewSystemPtr.GetSequenceSystem();
			List<CommandParam> commands = sequenceSystem.FindCommands(CommandNo.ParticleCreate);
			if (commands == null)
				return;
			int dataIndex = 0;
			foreach (var command in commands)
			{
				if (command.IsAlreadyCalled && command.EndFrame < targetData.seqFrame)
					continue;
				if (!sequenceSystem.GetParticleHashTable().TryGetVector(command.GroupNo, out HashSet<Dpr.Battle.View.Objects.BtlvEffectInstance> particles))
					continue;
				int count = 0;
				foreach (var particle in particles)
				{
					if (dataIndex + count >= targetData.wazaEffectDatas.Length)
						break;
					// read before the lazy allocation below (01c6f854)
					ParticleSystem particleSystem = particle.Effect.particleSystem;
					if (targetData.wazaEffectDatas[dataIndex + count] == null)
						targetData.wazaEffectDatas[dataIndex + count] = new WazaEffectData();
					targetData.wazaEffectDatas[dataIndex + count].groupNo = command.GroupNo;
					targetData.wazaEffectDatas[dataIndex + count].particlePlayTime = particleSystem.time;
					Transform particleTransform = particleSystem.transform;
					targetData.wazaEffectDatas[dataIndex + count].particlePosition = particleTransform.position + targetData.offsetPos;
					targetData.wazaEffectDatas[dataIndex + count].particleEulerAngle = particleTransform.eulerAngles;
					targetData.wazaEffectDatas[dataIndex + count].particleScale = particleTransform.localScale;
					count++;
				}
				dataIndex += count;
			}
		}
		private void SetCaptureData(global::Dpr.Contest.CaptureData target) {
			target.bAlreadyCapture = true;
			target.seqFrame = GetCaptureCommandFrame(target);
			SceneObjectManager objectManager = SceneObjectManager.Instance;
			ContestPlayerEntity userEntity = objectManager.GetUserEntity();
			Dpr.Battle.View.Objects.BOCamera camera;
			Dpr.Battle.View.Objects.BOPokemon pokemon;
			Transform pokemonTransform;
			if (target.viewSystemPtr.SystemType == ContestViewSystem.ViewSystemType.Main)
			{
				camera = objectManager.MainBOCamera;
				pokemon = userEntity.BoPokemon;
				pokemonTransform = pokemon.transform;
			}
			else
			{
				camera = objectManager.WazaBOCamera;
				if (wazaCaptureData.wazaNo == (int)WazaNo.HENSIN)
				{
					pokemon = objectManager.SpecialWazaModel;
					PokemonParam param = pokemon.Param;
					wazaCaptureData.monsNo = (int)param.GetMonsNo();
					wazaCaptureData.formNo = param.GetFormNo();
					wazaCaptureData.sex = (int)param.GetSex();
					wazaCaptureData.rare = param.IsRare();
				}
				else
				{
					pokemon = userEntity.WazaPokemon;
				}
				target.offsetPos.x = -100f;
				SetWazaEffectData(target);
				if (!userEntity.IsActiveWazaPokemon && wazaCaptureData.wazaNo == (int)WazaNo.MIGAWARI)
					pokemonTransform = pokemon.MigawariObject.transform;
				else
					pokemonTransform = pokemon.transform;
			}
			target.pokePosition = pokemonTransform.position + target.offsetPos;
			target.pokeEulerAngle = pokemonTransform.eulerAngles;
			target.pokeScale = pokemonTransform.localScale;
			var animationPlayer = pokemon.Entity.GetAnimationPlayer();
			target.motionIndex = animationPlayer.currentIndex;
			target.motionPlayTime = animationPlayer.currentPlayingTime;
			target.monitorIndex = objectManager.NowMonitorIndex;
			target.monitorPlayTime = objectManager.NowMonitorPlayTime;
			Transform cameraTransform = camera.transform;
			target.camPosition = cameraTransform.position + target.offsetPos;
			target.camEulerAngle = cameraTransform.eulerAngles;
			if (camera != null)
			{
				// GetPostEffects() / GetPfxParam() inlined: one _postEffects read, three fields (01c6f52c)
				PfxParam pfxParam = camera.GetPostEffects().GetPfxParam();
				target.dofDistance = pfxParam.dofDistance;
				target.dofFocalLength = pfxParam.dofFocalLength;
				target.dofFarDepth = pfxParam.dofFarDepth;
				// GetTargetTransform() inlined (m_targetTransform +0xC0), kept in a register across op_Inequality
				Transform dofTarget = camera.GetTargetTransform();
				if (dofTarget != null)
				{
					Vector3 dofTargetPos = dofTarget.position + target.offsetPos;
					target.dofTargetPosX = dofTargetPos.x;
					target.dofTargetPosY = dofTargetPos.y;
					target.dofTargetPosZ = dofTargetPos.z;
				}
			}
			else
			{
				ContestUtils.EmitLog("On Capture Photo : BoCamera is null!!!", LogType.Error);
			}
		}
		private int GetCaptureCommandFrame(global::Dpr.Contest.CaptureData target) {
			ContestViewSystem viewSystem = target.viewSystemPtr;
			ContestViewSystem.ViewSystemType systemType = viewSystem.SystemType;
			List<CommandParam> commands = viewSystem.GetSequenceSystem().FindCommands(CommandNo.ContestCaptureScene);
			if (systemType == ContestViewSystem.ViewSystemType.Main)
			{
				if (commands.Count <= 0)
				{
					ContestUtils.EmitLog("Main : Find Capture Command Count is 0", LogType.Error);
					return -1;
				}
				return commands[maxCaptureCommandNum - captureCommandNum - 1].StartFrame;
			}
			if (commands.Count <= 0)
			{
				ContestUtils.EmitLog("Waza : Find Capture Command Count is 0", LogType.Error);
				return -1;
			}
			return commands[0].StartFrame;
		}
		private bool CheckCaptureProbability(int persent) {
			captureCommandNum--;
			if (captureCommandNum <= 0)
				return true;
			return global::UnityEngine.Random.Range(0, ContestDataConstants.PHOTO_PERSENT) < persent;
		}
