		public global::Dpr.Contest.ResultID CalcContestResult() {
			float successScoreRatio = danceSectionData.successScoreRatio;
			int maxTotalScore = danceSectionData.maxTotalScore;
			ContestPlayerEntity[] entities = SceneObjectManager.Instance.GetPlayerEntities();
			int totalScore = 0;
			for (int i = 0; i < entities.Length; i++)
			{
				// ContestPlayerEntity.CalcTotalScore inlined (danceScore + heartNum + skillScore)
				int score = entities[i].CalcTotalScore();
				totalScore += score;
				ContestUtils.EmitLog(string.Format("Calc ResultID : Player[{0}] - Score [{1}]", entities[i].Index, score));
			}
			float scoreRatio = (float)totalScore / maxTotalScore;
			ContestUtils.EmitLog(string.Format("Calc ResultID : Score [{0}]/[{1}] : [{2}]/[{3}]", totalScore, maxTotalScore, scoreRatio, successScoreRatio));
			return scoreRatio < successScoreRatio ? ResultID.Failed : ResultID.Success;
		}
