			resultData.maxTotalScore = danceSectionData.maxTotalScore;
			resultData.categoryID = ContestWork.categoryID;
			resultData.rankID = ContestWork.rankID;
			// GetPlayerMonsNo / GetPlayerWazaNo inlined (their prologue flags 0x4cbdb3d / 0x4cbdb3e mid-body)
			resultData.monsNo = GetPlayerMonsNo();
			resultData.wazaNo = GetPlayerWazaNo();
			resultData.playerFashion = ContestWork.playerFashion;
			resultData.SetPlayerDataModelArray(CreateResultPlayerData());
			if (ContestWork.IsMultiMode)
			{
				resultData.isMultiMode = true;
