		private global::Dpr.Contest.ResultPlayerDataModel[] CreateResultPlayerData() {
			ContestPlayerEntity[] entities = SceneObjectManager.Instance.GetPlayerEntities();
			var resultPlayerDatas = new ResultPlayerDataModel[entities.Length];
			// FindTopScore inlined (same shape as its own body @01c705b0, placed right after this method's block)
			int topScore = FindTopScore(entities);
			for (int i = 0; i < entities.Length; i++)
			{
				var resultPlayerData = new ResultPlayerDataModel();
				AContestPlayerData playerData = entities[i].PlayerData;
				resultPlayerData.playerIndex = playerData.index;
				resultPlayerData.userNickName = playerData.playerInfo.nickname;
				resultPlayerData.localizeNickName = playerData.playerInfo.LocalizeNickName();
				resultPlayerData.playerSex = playerData.playerInfo.sex;
				resultPlayerData.playerLangID = playerData.playerInfo.langID;
				resultPlayerData.partnerNickName = playerData.pokemonInfo.nickname;
				resultPlayerData.monsSex = playerData.pokemonInfo.pokeParam.GetSex();
				resultPlayerData.monsLangID = (MessageEnumData.MsgLangId)playerData.pokemonInfo.pokeParam.GetLangId();
				resultPlayerData.visualScore = playerData.visualDataModel.heartNum;
				PlayerDanceDataModel danceDataModel = playerData.danceDataModel;
				resultPlayerData.danceScore = danceDataModel.danceScore;
				resultPlayerData.wazaScore = danceDataModel.skillScore;
				resultPlayerData.bestTimingCount = danceDataModel.GetTapTimingCount(NoteTapTimingID.Best);
				resultPlayerData.greatTimingCount = danceDataModel.GetTapTimingCount(NoteTapTimingID.Great);
				resultPlayerData.niceTimingCount = danceDataModel.GetTapTimingCount(NoteTapTimingID.Nice);
				resultPlayerData.missTimingCount = danceDataModel.GetTapTimingCount(NoteTapTimingID.MissFast) + danceDataModel.GetTapTimingCount(NoteTapTimingID.MissSlow);
				resultPlayerData.isBestPlayer = topScore <= resultPlayerData.GetTotalScore();
				resultPlayerDatas[i] = resultPlayerData;
			}
			return resultPlayerDatas;
		}
		private int FindTopScore(global::Dpr.Contest.ContestPlayerEntity[] entities) {
			int topScore = entities[0].CalcTotalScore();
			for (int i = 1; i < entities.Length; i++)
			{
				int score = entities[i].CalcTotalScore();
				if (topScore < score)
					topScore = score;
			}
			return topScore;
		}
		private void SetResultVoiceData(bool isUserWin) {
			PokemonParam pokeParam = SceneObjectManager.Instance.GetPlayerEntities()[userIndex].PlayerData.pokemonInfo.pokeParam;
			switch (pokeParam.GetMonsNo())
			{
				case MonsNo.IIBUI:
					resultData.isPlayVoice = true;
					resultData.CreateVoiceEventName(MonsNo.IIBUI, pokeParam.GetFormNo(), GetValueData(isUserWin ? 10 : 11));
					break;
				case MonsNo.PIKATYUU:
					resultData.isPlayVoice = true;
					resultData.CreateVoiceEventName(MonsNo.PIKATYUU, pokeParam.GetFormNo(), GetValueData(isUserWin ? 8 : 9));
					break;
			}
		}
		public void CreateMultiModeResultData(int result) {
			resultData.ResetData();
			resultData.isMultiMode = true;
			resultData.multiResult = result;
			if (result == 2)
				ContestWork.entryPlayerDatas = null;
		}
		public void OnFinishedContest() {
			// ApplyResultDataIntoPlayerWork inlined (its prologue flag 0x4cbdb4a right after this method's own)
			ApplyResultDataIntoPlayerWork();
			ApplyContestRewardData();
			if (ContestWork.categoryID != CategoryID.Tutorial)
			{
				ContestWork.ApplyContestRecord(contestResultDataModel);
				if (contestResultDataModel.bIsMulti)
					ContestWork.ApplyReportData_MultiMode(resultData);
				else
					ContestWork.ApplyContestTVData();
			}
			CheckCaptureData();
			SmartPoint.Components.Fader.fillColor = BattleViewDefine.BATTLE_FADE_OUT_FADER_COLOR;
			PlayerWork.isContest = false;
			PlayerWork.SetTransitionZone(PlayerWork.zoneID, -1);
			System.GC.Collect();
		}
		private void ApplyResultDataIntoPlayerWork() {
			if (ContestWork.categoryID != CategoryID.Tutorial && !resultData.isMultiMode)
				resultData.ApplyContestPoint();
		}
		private void ApplyContestRewardData() {
			contestResultDataModel.ResetParam();
			if (resultData.isMultiMode)
			{
				contestResultDataModel.bIsMulti = true;
				contestResultDataModel.multiResult = resultData.multiResult;
			}
			else
			{
				contestResultDataModel.categoryID = ContestWork.categoryID;
				contestResultDataModel.rankID = ContestWork.rankID;
				contestResultDataModel.resultID = resultData.resultID;
				if (contestResultDataModel.resultID == ResultID.Success)
					CheckClearContestFlag();
				if (!IsTutorial)
				{
					contestResultDataModel.bIsBestPerformer = resultData.IsUserWin();
					if (contestResultDataModel.bIsBestPerformer)
					{
						PokemonParam targetPokeParam = PlayerWork.playerParty.GetMemberPointer(ContestWork.selectPartyIndex);
						CheckContestReward(targetPokeParam);
						// CheckMasterContestReward inlined (flag-less; placed right after CheckContestReward = referenced here)
						CheckMasterContestReward(targetPokeParam);
					}
				}
			}
			ContestWork.SetResultData(contestResultDataModel);
		}
		private void CheckClearContestFlag() {
			if (!useContestData.isSaveClearFlag)
				return;
			CategoryID categoryID = contestResultDataModel.categoryID;
			RankID rankID = contestResultDataModel.rankID;
			Dpr.EvScript.EvWork.SYSFLAG_INDEX flagIndex;
			if (categoryID == CategoryID.Fur)
				flagIndex = ContestWork.FindSercretContestClearFlagIndex(rankID);
			else
				flagIndex = ContestWork.FindStandardContestClearFlagIndex(categoryID, rankID);
			// the int overloads are called (0x2C4EB00 / 0x2C4E8E0)
			Dpr.EvScript.EvDataManager evDataManager = Dpr.EvScript.EvDataManager.Instanse;
			if (evDataManager.GetSysFlag((int)flagIndex) <= 0)
			{
				evDataManager.SetSysFlag((int)flagIndex, true);
				ContestUtils.EmitLog(string.Format("Set Clear Flag True : {0}", flagIndex));
			}
		}
		private void CheckContestReward(global::Pml.PokePara.PokemonParam targetPokeParam) {
			if (targetPokeParam == null)
			{
				ContestUtils.EmitLog(string.Format("Player Party Index {0} Not Found", ContestWork.selectPartyIndex), LogType.Error);
				return;
			}
			CheckRewardCategoryRibbon(targetPokeParam);
			CheckRewardItem();
			CheckRewardClearAllMasterRank(targetPokeParam);
		}
		private void CheckRewardItem() {
			if (contestResultDataModel.categoryRibbon != (uint)RibbonNo.NULL)
				return;
			ContestMasterDatas.SheetRewardItemData rewardItemData = FindRewardItemData();
			if (rewardItemData == null)
			{
				ContestUtils.EmitLog(string.Format("Reward Item Data Not Found : {0} - {1}", contestResultDataModel.categoryID, contestResultDataModel.rankID), LogType.Error);
				return;
			}
			contestResultDataModel.itemNo = rewardItemData.itemNo;
			if (contestResultDataModel.itemNo <= 0)
				return;
			ContestWork.AddRewardItem((SealID)rewardItemData.itemNo, rewardItemData.itemCount);
			ContestUtils.EmitLog(string.Format("Add Item : ItemNo [{0}] - count {1}", (SealID)rewardItemData.itemNo, rewardItemData.itemCount));
		}
		private global::XLSXContent.ContestMasterDatas.SheetRewardItemData FindRewardItemData() {
			int rewardItemNum = useRewardData.rewardItemNoArray.Length;
			int totalProbability = 0;
			foreach (int probability in useRewardData.probabilityArray)
				totalProbability += probability;
			int lotValue = global::UnityEngine.Random.Range(0, totalProbability);
			int rewardItemNo = 0;
			for (int i = 0; i < rewardItemNum; i++)
			{
				if (useRewardData.probabilityArray[i] <= 0)
					continue;
				lotValue -= useRewardData.probabilityArray[i];
				if (lotValue <= 0)
				{
					rewardItemNo = useRewardData.rewardItemNoArray[i];
					break;
				}
			}
			return System.Array.Find(contestMasterDatas.RewardItemData, x => x.id == rewardItemNo);
		}
		private void CheckRewardCategoryRibbon(global::Pml.PokePara.PokemonParam targetPokeParam) {
			if (useRewardData == null)
				return;
			uint ribbonNo = useRewardData.rewardRibbonNo;
			if (ribbonNo == (uint)RibbonNo.NULL || targetPokeParam.HaveRibbon(ribbonNo))
				return;
			targetPokeParam.SetRibbon(ribbonNo);
			contestResultDataModel.categoryRibbon = ribbonNo;
			ContestUtils.EmitLog(string.Format("{0} : Get Ribbon [{1}]", targetPokeParam.GetNickName(), (RibbonNo)ribbonNo));
		}
		private void CheckRewardClearAllMasterRank(global::Pml.PokePara.PokemonParam targetPokeParam) {
			if (!IsAllMasterRankClear(targetPokeParam))
				return;
			contestResultDataModel.contestStarRibbon = (uint)RibbonNo.CONTEST_STAR;
			if (!targetPokeParam.HaveRibbon((uint)RibbonNo.CONTEST_STAR))
			{
				targetPokeParam.SetRibbon((uint)RibbonNo.CONTEST_STAR);
				ContestUtils.EmitLog(string.Format("{0} : Get Ribbon [{1}]", targetPokeParam.GetNickName(), RibbonNo.CONTEST_STAR));
			}
			ContestWork.AddRewardItem(SealID.SEAL_SHOWMASTER_A, GetValueData(5));
			ContestUtils.EmitLog("Add SEAL_SHOWMASTER_A");
		}
		private bool IsAllMasterRankClear(global::Pml.PokePara.PokemonParam targetPokeParam) {
			// `(categoryID & ~1) == 6` @01c71334
			if (contestResultDataModel.categoryID == CategoryID.Tutorial || contestResultDataModel.categoryID == CategoryID.Fur)
				return false;
			if (ContestWork.rankID != RankID.Master)
				return false;
			if (targetPokeParam.HaveRibbon((uint)RibbonNo.CONTEST_STAR))
				return false;
			// five-step constant loop, fully unrolled (01c71380-01c71450)
			for (uint ribbonNo = (uint)RibbonNo.STYLE_MASTER; ribbonNo <= (uint)RibbonNo.STRONG_MASTER; ribbonNo++)
			{
				if (contestResultDataModel.categoryRibbon != ribbonNo && !targetPokeParam.HaveRibbon(ribbonNo))
					return false;
			}
			return true;
		}
		private void CheckMasterContestReward(global::Pml.PokePara.PokemonParam targetPokeParam) {
			if (contestResultDataModel.categoryID == CategoryID.Fur && contestResultDataModel.rankID == RankID.Master && !targetPokeParam.HaveRibbon((uint)RibbonNo.TWINKLE_STAR))
			{
				targetPokeParam.SetRibbon((uint)RibbonNo.TWINKLE_STAR);
				contestResultDataModel.twinkleStarRibbon = (uint)RibbonNo.TWINKLE_STAR;
			}
		}
		private void CheckCaptureData() {
			// IsCaptureContest inlined (its prologue flag 0x4cbdb45 is this method's first flag)
			if (!IsCaptureContest() || !contestResultDataModel.IsBestPerformer)
				return;
			if (mainCaptureData.bAlreadyCapture && wazaCaptureData.bAlreadyCapture)
			{
				if (global::UnityEngine.Random.Range(0, useContestData.lotWazaPhoto + useContestData.lotMainPhoto) < useContestData.lotWazaPhoto)
					PerformSaveCaptureData(wazaCaptureData);
				else
					PerformSaveCaptureData(mainCaptureData);
			}
			else if (mainCaptureData.bAlreadyCapture)
			{
				PerformSaveCaptureData(mainCaptureData);
			}
			else if (wazaCaptureData.bAlreadyCapture)
			{
				PerformSaveCaptureData(wazaCaptureData);
			}
		}
		private void PerformSaveCaptureData(global::Dpr.Contest.CaptureData targetData) {
			ContestWork.SaveContestPhotoData(ContestCategoryID, (RankID)useContestData.rank, targetData);
		}
		public void ChangeTutorialSecondPlayData() {
			categoryTexNameSb.Clear();
			useNotesDataFilePathSb.Clear();
			useSequenceFilePathSb.Clear();
			categoryTexNameSb.Append(GetStringData(8));
			useNotesDataFilePathSb.Append(GetStringData(6));
			useSequenceFilePathSb.Append(string.Format(ContestDataConstants.SEQUENCE_FILE_PATH, GetStringData(2)));
			mainBgmEventID = Audio.AudioManager.Instance.GetIdByName(GetStringData(4));
			danceSectionData.musicBpm = GetValueData(4);
		}
		public float GetSyncScoreSpan() {
			// GetValueData inlined (no metadata, no flag): ValueData[15].value, scvtf + fdiv 1000f @01c62f3c
			return GetValueData(15) / 1000f;
		}
